package vn.svframe.worldboss;
import java.util.*;import net.minecraft.entity.*;import net.minecraft.entity.mob.*;import net.minecraft.entity.effect.*;import net.minecraft.particle.*;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.server.world.ServerWorld;import net.minecraft.util.math.*;import net.minecraft.util.hit.HitResult;import net.minecraft.world.RaycastContext;import net.minecraft.text.Text;import net.minecraft.sound.*;import vn.svframe.fantasyhub.protocol.*;import vn.svframe.svframelib.entity.NativeMobFactories;
/** Tick driven, fixed warning footprints; never edits arena blocks. */
final class CosmicEncounter {
 static final java.util.Set<UUID> MINIONS=new java.util.HashSet<>();
 final UUID owner;final MobEntity actor;final ServerWorld world;final BossConfig.Boss boss;final Vec3d center;final double radius;final List<MobEntity> minions=new ArrayList<>();
 final Map<UUID,Double> threat=new HashMap<>();final List<Vec3d> marks=new ArrayList<>();long tick,ready=40,impact,end,shieldUntil;int skill,rotation,phase=1;boolean snapped;Vec3d aim;UUID victim,prison;double shield;long prisonUntil;String stage="READY";
 CosmicEncounter(MobEntity actor,BossConfig.Boss boss,BossConfig.Arena arena){this(actor,boss,arena,null);}
 CosmicEncounter(MobEntity actor,BossConfig.Boss boss,BossConfig.Arena arena,UUID owner){this.owner=owner;this.actor=actor;this.boss=boss;world=(ServerWorld)actor.getWorld();center=new Vec3d(arena.x,arena.y,arena.z);radius=arena.radius;}
 List<ServerPlayerEntity> players(){return world.getPlayers(p->(owner==null||owner.equals(p.getUuid()))&&p.isAlive()&&!p.isSpectator()&&!p.isCreative()&&!InfinityRuntime.peace(p)&&p.squaredDistanceTo(center)<radius*radius);}
 void reconnectGrace(){
  if(impact>0){long extra=Math.max(0,tick+40-impact);impact+=extra;end+=extra;ready+=extra;shieldUntil+=extra;}
  else ready=Math.max(ready,tick+40);
 }
 void credit(UUID p,double damage){threat.merge(p,damage,Double::sum);}
 boolean shielded(){return tick<shieldUntil;}
 void close(){if(prison!=null){var p=world.getServer().getPlayerManager().getPlayer(prison);if(p!=null)InfinityRuntime.thaw(p);InfinityRuntime.prisons.remove(prison);prison=null;}actor.setInvisible(false);actor.setInvulnerable(false);actor.setNoGravity(false);for(var m:minions){MINIONS.remove(m.getUuid());m.discard();}minions.clear();}
 Map<String,Object> status(){return Map.of("stage",stage,"remainingTicks",Math.max(0,impact>tick?impact-tick:ready-tick),"skill",name(skill),"radius",skill==0?6:skill==2?3.5:radius);}
 String name(int s){return switch(s){case 0->"Titan Punch";case 1->"Titan Beam";case 2->"Cosmic Rain";case 3->"Infinity Snap — HIDE BEHIND PILLARS";case 4->"Curator Stasis — HIT THE PRISON TO FREE YOUR ALLY";case 5->"Artifact Requisition";case 6->"Menagerie Breach";case 7->"Reality Fracture";case 8->"You Belong To Me";default->"Exotic Energies";};}
 void trial(){if(tick%300!=1)return;String[] heroes={"THOR","SORCERER_SUPREME","SPIDER_MAN","BATMAN","FLASH","IRON_MAN"};String hero=heroes[(int)(tick/300)%heroes.length];((HeroNpcEntity)actor).hero(hero);vn.svframe.fantasyhub.core.hero.HeroNpcCombat.configure(actor,List.of(),boss.cooldown( actor.getHealth()/actor.getMaxHealth()),boss.damage(actor.getHealth()/actor.getMaxHealth()));vn.svframe.fantasyhub.core.hero.HeroNpcCombat.configureTiming(actor,boss.windupSeconds*20,boss.attackSeconds*20,0xAA55FF);actor.equipStack(EquipmentSlot.MAINHAND,hero.equals("THOR")?new net.minecraft.item.ItemStack(Protocol.stormbreaker):net.minecraft.item.ItemStack.EMPTY);try{var c=Class.forName("vn.svframe.svframeitems.SVFrameItems");var generator=c.getMethod("generator").invoke(null);for(var slot:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET)){String part=switch(slot){case HEAD->"helmet";case CHEST->"chestplate";case LEGS->"leggings";default->"boots";};actor.equipStack(slot,(net.minecraft.item.ItemStack)generator.getClass().getMethod("generate",String.class,int.class).invoke(generator,"hero_"+hero.toLowerCase(java.util.Locale.ROOT)+"_"+part,1));}}catch(Exception ex){org.slf4j.LoggerFactory.getLogger("WorldBoss").warn("Trial cosmetic item unavailable for {}; continuing native skills",hero);}for(var p:players())p.sendMessage(Text.literal("§5Ultimate Test: "+hero),true);}
 double setting(String key,double fallback){return boss.mechanics.getOrDefault(key,fallback);}
 void tick(){if(actor.getCommandTags().contains("svframe_cosmic_frozen"))return;tick++;if(!actor.isAlive())return;if(boss.classId.equals("GAUNTLET_TRIAL")){trial();return;}var ps=players();if(tick>=shieldUntil){actor.setInvulnerable(false);actor.setInvisible(false);if(skill==3)actor.setNoGravity(false);}if(ps.isEmpty()){actor.getNavigation().stop();return;}
 var target=ps.stream().max(Comparator.comparingDouble(p->threat.getOrDefault(p.getUuid(),0d))).orElse(ps.getFirst());actor.getLookControl().lookAt(target,35,35);
 if(prison!=null){var trapped=world.getServer().getPlayerManager().getPlayer(prison);if(tick>=prisonUntil||trapped==null)prison=null;else if(tick%4==0)ring(trapped.getPos(),1.6,0xAA55FF);}
 if(boss.classId.equals("THANOS")&&!snapped&&actor.getHealth()/actor.getMaxHealth()<=.5){snapped=true;begin(3,target,100);return;}
 if(impact>tick){stage="WINDUP";if(tick%3==0){for(var p:marks)ring(p,skill==0?6:skill==2?3.5:skill==3?radius:skill==9?10:2,0xA050FF);if(skill==1)line(actor.getEyePos(),aim,0xB040FF);}
  if(skill==0&&tick%3==0)for(var p:ps)if(p.squaredDistanceTo(actor)<36){p.addVelocity(actor.getPos().subtract(p.getPos()).normalize().multiply(.55));p.velocityModified=true;}
  return;}
 if(impact>0){impact=0;stage="ATTACK";execute(ps,target);}
 if(tick<end){stage="ATTACK";if(skill==1&&tick%4==0){var t=world.getServer().getPlayerManager().getPlayer(victim);if(t!=null)aim=aim.lerp(t.getEyePos(),.08);beam(aim,setting("beamDamage",6)*boss.damage( actor.getHealth()/actor.getMaxHealth()),0xAA33FF);}return;}
 if(tick<ready){stage="RECOVERY";return;}
 if(actor.squaredDistanceTo(target)>64)actor.getNavigation().startMovingTo(target,1.1);else actor.getNavigation().stop();
 int next;if(boss.classId.equals("THANOS"))next=rotation++%3;else{double h=actor.getHealth()/actor.getMaxHealth();phase=h>.85?1:h>.6?2:h>.3?3:4;next=switch(phase){case 1->rotation++%3==2?8:4;case 2->rotation++%3==2?9:5;case 3->rotation++%3==2?9:6;default->rotation++%2==0?7:9;};}
 begin(next,target,boss.windupSeconds*20);
 }
 void begin(int id,ServerPlayerEntity target,int windup){skill=id;victim=target.getUuid();aim=target.getEyePos();marks.clear();impact=tick+windup;end=impact+(id==1?60:0);ready=end+Math.max(20,(long)(boss.attackSeconds*20*boss.cooldown(actor.getHealth()/actor.getMaxHealth())));actor.getNavigation().stop();
 if(id==0||id==9)marks.add(actor.getPos());else if(id==2){for(var p:players())marks.add(p.getPos());impact=tick+(long)Math.ceil(30*setting("telegraphMultiplier",1));end=impact;ready=end+(long)(boss.attackSeconds*20*boss.cooldown(actor.getHealth()/actor.getMaxHealth()));shieldUntil=impact+5;actor.setInvisible(true);actor.setInvulnerable(true);}else if(id==3){marks.add(center);shieldUntil=impact;actor.setInvulnerable(true);actor.setNoGravity(true);actor.setVelocity(0,.35,0);}else if(id==7){for(var p:players())marks.add(p.getPos());}else marks.add(target.getPos());
 for(var p:players())p.sendMessage(Text.literal("§5"+name(id)+(id==3?" — use SOLID cover!":" — move out of the warning!")),true);world.playSound(null,actor.getBlockPos(),SoundEvents.BLOCK_BEACON_ACTIVATE,SoundCategory.HOSTILE,1,.6f);
 }
 void execute(List<ServerPlayerEntity> ps,ServerPlayerEntity target){double scale=boss.damage(actor.getHealth()/actor.getMaxHealth());switch(skill){
 case 0->{for(var p:ps)if(p.squaredDistanceTo(actor)<=36){hurt(p,setting("punchDamage",45)*scale,false);InfinityRuntime.freeze(p,25);p.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS,45,3));p.addStatusEffect(new StatusEffectInstance(StatusEffects.BLINDNESS,35,0));}ring(actor.getPos(),6,0xCC66FF);}
 case 1->beam(aim,setting("beamDamage",6)*scale,0xA020FF);
 case 2->{actor.setInvisible(false);for(var at:marks){line(at.add(0,14,0),at,0xFF6600);world.spawnParticles(ParticleTypes.EXPLOSION,at.x,at.y+.3,at.z,2,.2,.2,.2,0);for(var p:ps)if(p.squaredDistanceTo(at)<12.25){hurt(p,setting("meteorDamage",30)*scale,true);p.setOnFireFor(5);p.addStatusEffect(new StatusEffectInstance(StatusEffects.WITHER,80,1));}}}
 case 3->{actor.setNoGravity(false);actor.setVelocity(0,-.2,0);for(var p:ps){if(clear(actor.getPos().add(0,1.2,0),p.getPos().add(0,.8,0)))hurt(p,Math.max(1000,p.getMaxHealth()*10),true);}ring(center,radius,0xDD22FF);summon("dark");}
 case 4->{prison=target.getUuid();prisonUntil=tick+100;InfinityRuntime.freeze(target,100);target.addStatusEffect(new StatusEffectInstance(StatusEffects.BLINDNESS,100,0));target.sendMessage(Text.literal("§dStasis: an ally must strike you to break the prison."),false);InfinityRuntime.prisons.put(target.getUuid(),()->{prison=null;InfinityRuntime.thaw(target);});}
 case 5->{float stolen=0;for(var p:ps)stolen+=8*vn.svframe.fantasyhub.core.hero.HeroRuntime.stripPositiveBuffs(p);for(var p:ps)for(var e:List.copyOf(p.getStatusEffects()))if(e.getEffectType().value().isBeneficial()){stolen+=8*(e.getAmplifier()+1);p.removeStatusEffect(e.getEffectType());}var max=actor.getAttributeInstance(net.minecraft.entity.attribute.EntityAttributes.GENERIC_MAX_ABSORPTION);if(max!=null)max.setBaseValue(2000);actor.setAbsorptionAmount(Math.min(2000,actor.getAbsorptionAmount()+stolen));}
 case 6->summon("dark");
 case 7->{for(var p:ps){if(world.random.nextBoolean())p.addVelocity(0,1.2,0);else p.addVelocity(actor.getPos().subtract(p.getPos()).normalize().multiply(1.5));p.velocityModified=true;}for(var point:marks)beam(point,12*scale,0xFF9933);}
 case 8->{InfinityRuntime.confuse(target,60);target.sendMessage(Text.literal("§5You belong to me! Teammates: keep your distance."),true);}
 default->{for(var p:ps)if(p.squaredDistanceTo(actor)<100){hurt(p,setting("sweepDamage",26)*scale,true);p.setOnFireFor(3);p.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS,50,1));}for(int i=0;i<3;i++)ring(actor.getPos(),3+i*3,i==0?0xFF6600:i==1?0x88CCFF:0xFFFF66);}
 }}
 boolean releasePrison(ServerPlayerEntity prisoner,Entity attacker){return prison!=null&&prison.equals(prisoner.getUuid())&&attacker instanceof ServerPlayerEntity p&&!p.getUuid().equals(prison);}
 void summon(String type){
  minions.removeIf(m->{if(m.isRemoved()||!m.isAlive()){MINIONS.remove(m.getUuid());return true;}return false;});
  int available=Math.max(0,12-minions.size());for(int i=0;i<Math.min(4,available);i++)try{var f=NativeMobFactories.get("cobblemon:pokemon");if(f==null)return;var m=f.create(world,List.of("houndoom","umbreon","absol","weavile").get(i)+" level=80 alpha=true uncatchable=true unbattleable=true scale=1.6");var at=center.add((i%2==0?1:-1)*6,0,(i<2?1:-1)*6);m.refreshPositionAndAngles(at.x,at.y,at.z,0,0);m.addCommandTag("svframe_cosmic_minion");if(owner!=null)m.addCommandTag("svframe_minion_owner:"+owner);m.setPersistent();MINIONS.add(m.getUuid());if(world.isSpaceEmpty(m)&&world.spawnEntity(m))minions.add(m);else MINIONS.remove(m.getUuid());}catch(Exception ignored){} }
 void beam(Vec3d to,double damage,int color){var from=actor.getEyePos();var end=from.add(to.subtract(from).normalize().multiply(Math.min(radius*2,40)));var hit=world.raycast(new RaycastContext(from,end,RaycastContext.ShapeType.COLLIDER,RaycastContext.FluidHandling.NONE,actor));if(hit.getType()!=HitResult.Type.MISS)end=hit.getPos();line(from,end,color);for(var p:players())if(p.getBoundingBox().expand(.7).raycast(from,end).isPresent())hurt(p,damage,true);}
 boolean clear(Vec3d from,Vec3d to){return world.raycast(new RaycastContext(from,to,RaycastContext.ShapeType.COLLIDER,RaycastContext.FluidHandling.NONE,actor)).getType()==HitResult.Type.MISS;}
 void hurt(ServerPlayerEntity p,double amount,boolean magic){if(InfinityRuntime.peace(p))return;var d=new vn.svframe.svframelib.damage.DamageMetadata(amount,List.of(vn.svframe.svframelib.damage.DamageType.SKILL,magic?vn.svframe.svframelib.damage.DamageType.MAGIC:vn.svframe.svframelib.damage.DamageType.PHYSICAL));vn.svframe.svframelib.SVFrameLib.inst().getDamage().registerAttack(new vn.svframe.svframelib.damage.AttackMetadata(d,p,new vn.svframe.svframelib.api.stat.provider.EntityStatProvider(actor)),false,true,actor.getDamageSources().mobAttack(actor));}
 void ring(Vec3d at,double r,int color){var dust=new DustParticleEffect(new org.joml.Vector3f((color>>16&255)/255f,(color>>8&255)/255f,(color&255)/255f),1.5f);for(int i=0;i<72;i++){double a=i*Math.PI/36;world.spawnParticles(dust,at.x+Math.cos(a)*r,at.y+.15,at.z+Math.sin(a)*r,1,0,0,0,0);}}
 void line(Vec3d from,Vec3d to,int color){var dust=new DustParticleEffect(new org.joml.Vector3f((color>>16&255)/255f,(color>>8&255)/255f,(color&255)/255f),1.3f);int n=Math.min(120,(int)(from.distanceTo(to)*3)+1);for(int i=0;i<=n;i++){var p=from.lerp(to,i/(double)n);world.spawnParticles(dust,p.x,p.y,p.z,1,0,0,0,0);}}
}
